window.addEventListener('keydown',e=>{if(e.target.closest&&e.target.closest('.button'))return;const k=e.key.toLowerCase();if(S.phase!=='running'&&k!=='r')return;if([' ','arrowup','shift','x','e','p','r'].includes(k)){e.preventDefault();if(e.repeat)return;if(k===' '||k==='arrowup')jump();else if(k==='shift'||k==='x')dash();else if(k==='e')superMove();else if(k==='p')pause();else if(k==='r')start(S.mode)}});
